/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitPins
 * Description   : Configures pin routing and optionally pin electrical features.
 *
 * END ****************************************************************************************************************/
void BOARD_InitPins(void) {                                /*!< Function assigned for the core: undefined[cm33] */
    IOMUXC_SetPinMux(IOMUXC_PAD_UART2_RXD__LPUART2_RX, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_UART2_TXD__LPUART2_TX, 0U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_UART2_RXD__LPUART2_RX, 
                        IOMUXC_PAD_PD_MASK);
    IOMUXC_SetPinConfig(IOMUXC_PAD_UART2_TXD__LPUART2_TX, 
                        IOMUXC_PAD_DSE(15U));

    /* LPUART6: the telemetry link to the VTX. RX is pulled up so that an
     * unplugged line idles high instead of looking like a break. */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO05__LPUART6_RX, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO04__LPUART6_TX, 0U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO05__LPUART6_RX, 
                        IOMUXC_PAD_PU_MASK);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO04__LPUART6_TX, 
                        IOMUXC_PAD_DSE(15U));

    /* LPSPI4: the IMU link. All four pads run straight from the SoC to header
     * P11 on the FRDM board, so nothing else is loading them. FSEL1(2) is the
     * faster slew the SDK uses for SPI - the LPUART pads keep the slow setting
     * because they do not need the edge rate. Pull-downs keep the bus defined
     * while the master is idle or the IMU is absent. */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO18__LPSPI4_PCS0, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO19__LPSPI4_SIN, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO20__LPSPI4_SOUT, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO21__LPSPI4_SCK, 0U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO18__LPSPI4_PCS0,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_PD_MASK);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO19__LPSPI4_SIN,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_PD_MASK);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO20__LPSPI4_SOUT,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_PD_MASK);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO21__LPSPI4_SCK,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_PD_MASK);

    /*
     * I2C_INTERNAL_PULLUP - a way to try either I2C bus without a soldering
     * iron. Applies to both, because both have the same fault.
     *
     * Neither bus has its 3.3 V-side pull-ups fitted: R58/R54 on the
     * magnetometer bus, R57/R55 on the barometer bus, all DNP. Only the 1.8 V
     * sides are populated, and a MOSFET level translator needs both ends - so
     * out of the box nothing pulls the host side high. The symptom varies with
     * how the floating lines happen to settle, which is why the same hardware
     * has reported kStatus_LPI2C_Busy (900), Nak (902) and ArbitrationLost
     * (905) on different runs. Arbitration-lost is the clearest of the three:
     * it means the master released a line expecting it to rise and read it
     * back low, which is precisely what no pull-up looks like.
     *
     * Enabling the pads' internal pull-ups gives the lines something. It is a
     * DIAGNOSTIC, NOT A FIX: the internal pull-up is weak - tens of kilohms
     * against the 2.2k the board intends - so rise times are poor and this is
     * only plausible at 100 kHz, which is why i2c_driver.h drops both buses to
     * that rate when this is set. Anything that needs these buses to be
     * reliable still needs the resistors.
     *
     * What it buys is a clean answer. The u-blox GPS is a known-good I2C
     * device already wired to the barometer bus (the Pixhawk connector carries
     * DDC on the same GPIO_IO00/IO01 pair) and it answers at 0x42. If turning
     * this on makes 0x42 appear in baro_task's scan, the bus and the
     * translator are proven and the only thing missing is R55/R57.
     */
#ifndef I2C_INTERNAL_PULLUP
#define I2C_INTERNAL_PULLUP 0
#endif

#if I2C_INTERNAL_PULLUP
#define I2C_PAD_PULL IOMUXC_PAD_PU_MASK
#else
#define I2C_PAD_PULL 0U
#endif

    /*
     * LPI2C4: the BMM350 magnetometer bus, header P11 pins 3 (SDA) and 5 (SCL).
     * The sensor-board schematic calls this I2C6; the FRDM netlist calls the
     * same pins I2C4_SDA / I2C4_SCL.
     *
     * SION must be on - I2C is bidirectional and the peripheral has to read
     * back the line it is driving - and the pad is open-drain with no internal
     * pull, because the bus pull-ups belong on the board. Note the sensor
     * board leaves its 3.3 V-side pull-ups (R54, R58) unpopulated, so they
     * have to be fitted for this bus to run at all.
     */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO02__LPI2C4_SDA, 1U); /* 1U = SION */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO03__LPI2C4_SCL, 1U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO02__LPI2C4_SDA,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_OD_MASK |
                        I2C_PAD_PULL);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO03__LPI2C4_SCL,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_OD_MASK |
                        I2C_PAD_PULL);

    /*
     * LPI2C3: the BMP581 barometer bus, header P11 pins 27 (SDA) and 28 (SCL).
     * The sensor-board schematic calls this I2C5. The GPS connector's DDC pins
     * land on the same pair, so a default-configured u-blox module is a second
     * device on this bus at 0x42.
     *
     * Same pad treatment as LPI2C4: SION on, because I2C is bidirectional and
     * the peripheral has to read back the line it drives, and open-drain.
     *
     * I2C_INTERNAL_PULLUP is defined above both I2C blocks - see the note
     * there.
     */

    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO00__LPI2C3_SDA, 1U); /* 1U = SION */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO01__LPI2C3_SCL, 1U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO00__LPI2C3_SDA,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_OD_MASK |
                        I2C_PAD_PULL);
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO01__LPI2C3_SCL,
                        IOMUXC_PAD_DSE(15U) |
                        IOMUXC_PAD_FSEL1(2U) |
                        IOMUXC_PAD_OD_MASK |
                        I2C_PAD_PULL);

    /* LPUART3: the GPS link, header P11 pins 8 (TX) and 10 (RX). RX is pulled
     * up so an unplugged GPS idles high instead of looking like a break -
     * same reasoning as the VTX port on LPUART6. */
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO14__LPUART3_TX, 0U);
    IOMUXC_SetPinMux(IOMUXC_PAD_GPIO_IO15__LPUART3_RX, 0U);

    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO14__LPUART3_TX,
                        IOMUXC_PAD_DSE(15U));
    IOMUXC_SetPinConfig(IOMUXC_PAD_GPIO_IO15__LPUART3_RX,
                        IOMUXC_PAD_PU_MASK);
}

